return ['domain'=>'zinn-order-updates','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-order-updates','pot-creation-date'=>'2026-11-11T11:19:43+00:00','po-revision-date'=>'2026-11-11T11:19:43+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Order Updates'=>'Zinn® Order Updates','https://zinndigital.com/wordpress-plugins/zinn-order-updates'=>'https://zinndigital.com/wordpress-plugins/zinn-order-updates','SMS and WhatsApp order updates for your store, sent through Zinn® Campaigns under your store\'s own name. Connect in one click; no keys to paste.'=>'Aktualizace objednávek přes SMS a WhatsApp pro váš obchod, odesílané prostřednictvím Zinn® Campaigns pod vlastním názvem vašeho obchodu. Připojte se jedním kliknutím; žádné klíče ke vkládání.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Read and send SMS and WhatsApp order updates for this store.'=>'Čtěte a odesílejte aktualizace objednávek přes SMS a WhatsApp pro tento obchod.','The WooCommerce order ID.'=>'ID objednávky WooCommerce.','Get order messages'=>'Získat zprávy objednávky','Lists every SMS or WhatsApp update for one order, newest first, with its outcome. The phone number is masked.'=>'Uvádí každou aktualizaci přes SMS nebo WhatsApp pro jednu objednávku, od nejnovější, včetně jejího výsledku. Telefonní číslo je maskováno.','Send an order update'=>'Odeslat aktualizaci objednávky','Sends one approved order update (never free text) to the shopper of the order, only if they agreed to receive it. Reusing a request_id never sends twice.'=>'Odešle zákazníkovi objednávky jednu schválenou aktualizaci objednávky (nikdy volný text), pouze pokud souhlasil s jejím přijetím. Opětovné použití request_id nikdy neodešle zprávu dvakrát.','Which approved update to send.'=>'Kterou schválenou aktualizaci odeslat.','A unique ID for this send (8 to 64 letters, digits, dots, dashes or underscores). Send the same ID again to retry safely.'=>'Jedinečné ID pro toto odeslání (8 až 64 písmen, číslic, teček, pomlček nebo podtržítek). Chcete-li akci bezpečně zopakovat, odešlete stejné ID znovu.','Optional https tracking link for a shipped update.'=>'Volitelný https sledovací odkaz pro odeslanou aktualizaci.','Get connection health'=>'Zjistit stav připojení','Shows whether this store is connected to Zinn® Campaigns and what Zinn® Campaigns sees for it.'=>'Zobrazuje, zda je tento obchod připojen k Zinn® Campaigns a co pro něj Zinn® Campaigns vidí.','Choose one of the approved order updates.'=>'Vyberte jednu ze schválených aktualizací objednávky.','The request ID must be 8 to 64 letters, digits, dots, dashes or underscores.'=>'Identifikátor požadavku musí obsahovat 8 až 64 písmen, číslic, teček, pomlček nebo podtržítek.','Connect this store to Zinn® Campaigns first.'=>'Nejprve propojte tento obchod se službou Zinn® Campaigns.','There is no order with that ID on this store.'=>'V tomto obchodě neexistuje žádná objednávka s tímto ID.','Zinn® Campaigns could not be reached. Try again in a minute.'=>'K aplikaci Zinn® Campaigns se nepodařilo připojit. Zkuste to znovu za minutu.','Zinn® Campaigns refused the request.'=>'Služba Zinn® Campaigns požadavek odmítla.','Order Updates'=>'Aktualizace objednávky','Your store is connected to Zinn® Campaigns.'=>'Váš obchod je propojen se službou Zinn® Campaigns.','Your store is disconnected. No messages will be sent.'=>'Váš obchod je odpojen. Nebudou odesílány žádné zprávy.','That connection took too long or was started in another browser. Press Connect again.'=>'Toto připojení trvalo příliš dlouho nebo bylo zahájeno v jiném prohlížeči. Stiskněte znovu Připojit.','Zinn® did not accept the connection. Press Connect again; if it keeps failing, contact Zinn® support.'=>'Zinn® nepřijal připojení. Stiskněte znovu „Připojit“; pokud problém přetrvává, kontaktujte podporu Zinn®.','Your site could not reach Zinn®. Check that your host allows outgoing connections, then press Connect again.'=>'Váš web se nemohl spojit se Zinn®. Zkontrolujte, zda váš hosting povoluje odchozí připojení, a poté stiskněte „Znovu připojit“.','Help'=>'Nápověda','Send your customers SMS and WhatsApp updates about their orders, under your store\'s own name, paid from your Zinn® credit.'=>'Posílejte svým zákazníkům aktualizace o jejich objednávkách přes SMS a WhatsApp pod vlastním názvem svého obchodu, hrazené z vašeho kreditu Zinn®.','Connect opens Zinn® in this window. Sign in or create an account, approve this store, and you come straight back here. You never paste a key.'=>'Propojit otevře Zinn® v tomto okně. Přihlaste se nebo si vytvořte účet, schvalte tento obchod a vrátíte se přímo sem. Nikdy nevkládáte žádný klíč.','Connect to Zinn® Campaigns'=>'Připojit k Zinn® Campaigns','Connected, but Zinn® could not be reached just now. We will try again shortly.'=>'Připojeno, ale k Zinn® se právě teď nepodařilo připojit. Za chvíli to zkusíme znovu.','Store'=>'Obchod','Connected'=>'Připojeno','Zinn® Campaigns'=>'Zinn® Campaigns','Open for your account'=>'Otevřeno pro váš účet','Not open for your account yet. Zinn® will e-mail you when it is.'=>'Pro váš účet zatím není k dispozici. Až bude k dispozici, Zinn® vám pošle e-mail.','Disconnect'=>'Odpojit','You are not allowed to connect this store.'=>'Nemáte oprávnění připojit tento obchod.','You are not allowed to disconnect this store.'=>'Nemáte oprávnění odpojit tento obchod.','Send me order updates by SMS to my phone number. Message and data rates may apply. Reply STOP to stop.'=>'Zasílejte mi aktualizace objednávky prostřednictvím SMS na mé telefonní číslo. Mohou být účtovány poplatky za zprávy a data. Pro zrušení odpovězte STOP.','Connection'=>'Připojení','You are not allowed to do that.'=>'K této akci nemáte oprávnění.','Thank you. You can now ask for help and send reports to Zinn® support.'=>'Děkujeme. Nyní můžete požádat o pomoc a odesílat hlášení podpoře Zinn®.','Consent withdrawn. Nothing is sent to Zinn® support until you agree again.'=>'Souhlas byl odvolán. Podpoře Zinn® se nic neodešle, dokud znovu neudělíte souhlas.','The Zinn® AI could not answer just now. Send your question to the team below; a person will reply.'=>'Umělá inteligence Zinn® právě teď nemohla odpovědět. Pošlete svůj dotaz týmu níže; odpoví vám člověk.','Glad that solved it.'=>'Jsme rádi, že se to tím vyřešilo.','Sent. Your ticket is %s; the team replies here and by e-mail.'=>'Odesláno. Váš požadavek je %s; tým odpoví zde a e-mailem.','Fill in the subject, the message and, while your store is not connected, your e-mail address.'=>'Vyplňte předmět, zprávu a dokud není váš obchod připojen, také vaši e-mailovou adresu.','Zinn® did not accept the ticket. Check the fields and try again; if it keeps failing, e-mail support@zinndigital.com.'=>'Zinn® nepřijal tiket. Zkontrolujte pole a zkuste to znovu; pokud problém přetrvává, napište na e-mail support@zinndigital.com.','Too many requests in a short time. Wait a few minutes and try again.'=>'Příliš mnoho požadavků v krátkém čase. Počkejte prosím několik minut a zkuste to znovu.','Reply sent.'=>'Odpověď byla odeslána.','That ticket is closed. Send a new ticket instead.'=>'Tento požadavek je uzavřen. Místo toho odešlete nový požadavek.','Your reply could not be sent. Try again in a moment.'=>'Vaši odpověď se nepodařilo odeslat. Zkuste to za chvíli znovu.','Waiting on Zinn® support'=>'Čeká se na podporu Zinn®','Waiting on you'=>'Čeká se na vás','Answered'=>'Zodpovězeno','Closed'=>'Zavřeno','Report a bug'=>'Nahlásit chybu','Send feedback'=>'Odeslat zpětnou vazbu','Request a feature'=>'Požádat o funkci','Ask for help'=>'Požádat o pomoc','Versions: WordPress, PHP, this plugin, WooCommerce (and whether it uses HPOS) and the supported plugins we detected'=>'Verze: WordPress, PHP, tento plugin, WooCommerce (a zda používá HPOS) a zjištěné podporované pluginy','Your active theme and its version'=>'Vaše aktivní šablona a její verze','The list of installed plugins, their versions and whether each is active'=>'Seznam nainstalovaných pluginů, jejich verze a informace o tom, zda je každý z nich aktivní','Connection: your store address, whether it is connected, this install\'s id and whether Zinn® answered its last check (never the store\'s token)'=>'Připojení: adresa vašeho obchodu, zda je připojen, ID této instalace a zda Zinn® odpověděl na svou poslední kontrolu (nikdy token obchodu)','Zinn® Order Updates: Help'=>'Aktualizace objednávek Zinn®: Nápověda','Withdraw my consent to send help requests'=>'Odvolat můj souhlas se zasíláním žádostí o pomoc','Help here is answered by Zinn Digital® Ltd. Before anything leaves your site, this is exactly what is sent, and where:'=>'Nápovědu zde poskytuje společnost Zinn Digital® Ltd. Než cokoli opustí Váš web, zde je přesně uvedeno, co a kam se odesílá:','A question you type: sent to the Zinn® AI at api.zinndigital.com, which answers from the Zinn® help articles.'=>'Otázka, kterou zadáte: odešle se do Zinn® AI na api.zinndigital.com, která odpovídá z článků nápovědy Zinn®.','A ticket you send: its subject, your message, your admin language and a reply e-mail address, sent to Zinn® support.'=>'Tiket, který odešlete: jeho předmět, vaše zpráva, váš jazyk administrace a e-mailová adresa pro odpověď, odeslané podpoře Zinn®.','Diagnostics: only the blocks you tick, each shown in full before you send. Never the store\'s token, passwords or your customers\' details.'=>'Diagnostika: pouze bloky, které zaškrtnete, každý se před odesláním zobrazí v plném rozsahu. Nikdy token obchodu, hesla ani údaje Vašich zákazníků.','Your tickets: while your store is connected, this screen reads your tickets and the team\'s replies from Zinn®.'=>'Vaše požadavky: dokud je váš obchod připojen, tato obrazovka načítá vaše požadavky a odpovědi týmu ze Zinn®.','We record who agreed and when. You can withdraw at any time on this screen.'=>'Zaznamenáváme, kdo a kdy souhlasil. Na této obrazovce můžete svůj souhlas kdykoli odvolat.','Agree and continue'=>'Souhlasit a pokračovat','Ask the Zinn® AI'=>'Zeptejte se Zinn® AI','What do you need help with?'=>'S čím potřebujete pomoci?','Ask'=>'Zeptejte se','Help articles'=>'Nápověda – články','That solved it'=>'Tím se to vyřešilo','Still need help? Send it to the team below.'=>'Stále potřebujete pomoc? Pošlete to týmu níže.','Send it to the Zinn® team'=>'Odešlete to týmu Zinn®','What is it?'=>'Co je to?','Subject'=>'Předmět','What happened? For a bug, the steps that show it.'=>'Co se stalo? V případě chyby uveďte kroky, které ji ukazují.','Reply e-mail'=>'E-mail pro odpověď','Leave empty to use the e-mail of the Zinn® member who connected this store.'=>'Ponechte prázdné, pokud chcete použít e-mail člena Zinn®, který tento obchod připojil.','Your store is not connected, so the team replies by e-mail.'=>'Váš obchod není připojen, proto tým odpovídá e-mailem.','Diagnostics (optional). Tick a block to attach it; this is exactly what is sent.'=>'Diagnostika (volitelné). Zaškrtněte blok pro jeho přiložení; přesně toto se odešle.','Send to Zinn® support'=>'Odeslat podpoře Zinn®','My tickets'=>'Moje požadavky','Connect your store to follow your tickets here. Until then the team replies by e-mail.'=>'Připojte svůj obchod, abyste zde mohli sledovat své požadavky. Do té doby tým odpovídá e-mailem.','Your tickets could not be loaded just now. Try again in a moment.'=>'Vaše tikety se právě nepodařilo načíst. Zkuste to za chvíli znovu.','No tickets yet.'=>'Zatím žádné požadavky.','Zinn® support replied on %s:'=>'Podpora Zinn® odpověděla %s:','Your reply'=>'Vaše odpověď','Send reply'=>'Odeslat odpověď','Zinn Digital®'=>'Zinn Digital®','Zinn® SMS and WhatsApp sign-up'=>'Registrace k odběru přes SMS a WhatsApp od Zinn®','Lets visitors sign up for offers and news by SMS or WhatsApp. Unticked by default; marketing only.'=>'Umožňuje návštěvníkům přihlásit se k odběru nabídek a novinek prostřednictvím SMS nebo aplikace WhatsApp. Ve výchozím stavu nezaškrtnuto; pouze pro marketingové účely.','Sign-up settings'=>'Nastavení registrace','Channel'=>'Kanál','SMS'=>'SMS','WhatsApp'=>'WhatsApp','Visitor chooses SMS or WhatsApp'=>'Návštěvník si vybere SMS nebo WhatsApp','Zinn® SMS offers consent'=>'Souhlas se SMS nabídkami Zinn®','Zinn® WhatsApp offers consent'=>'Souhlas s nabídkami Zinn® přes WhatsApp','Records a marketing opt-in in Zinn® Campaigns for the phone number in this form.'=>'Zaznamená souhlas s marketingem v Zinn® Campaigns pro telefonní číslo v tomto formuláři.','Send me offers and news on WhatsApp to this number. Optional; unsubscribe any time.'=>'Zasílejte mi na toto číslo nabídky a novinky přes WhatsApp. Volitelné; odběr můžete kdykoli zrušit.','Send me offers and news by SMS to this number. Optional; unsubscribe any time by replying STOP. Message and data rates may apply.'=>'Zasílejte mi nabídky a novinky prostřednictvím SMS na toto číslo. Volitelné; odběr můžete kdykoli zrušit odesláním odpovědi STOP. Mohou být účtovány poplatky za zprávy a data.','Connect this store to Zinn® Campaigns to show this sign-up form.'=>'Pro zobrazení tohoto registračního formuláře propojte tento obchod se službou Zinn® Campaigns.','Mobile number'=>'Telefonní číslo','How should we send them?'=>'Jak je máme odeslat?','Send me offers and news by the channel I chose above. Optional; unsubscribe any time.'=>'Zasílejte mi nabídky a novinky prostřednictvím kanálu, který jsem vybral(a) výše. Volitelné; odběr můžete kdykoli zrušit.','Leave this empty'=>'Ponechte prázdné','Sign up'=>'Zaregistrujte se','Thank you, you are signed up. You can unsubscribe any time.'=>'Děkujeme vám, jste zaregistrováni. Odběr můžete kdykoli zrušit.','Please enter your mobile number with its country code, for example +44 7700 900123.'=>'Zadejte prosím své mobilní číslo s předvolbou země, například +44 7700 900123.','Please tick the box to agree.'=>'Pro souhlas zaškrtněte políčko.','This form was open for a long time. Please reload the page and send it again.'=>'Tento formulář byl otevřen příliš dlouho. Obnovte prosím stránku a odešlete jej znovu.','Too many sign-ups from here. Please wait a few minutes and try again.'=>'Příliš mnoho registrací z tohoto místa. Počkejte prosím několik minut a zkuste to znovu.','We could not save your sign-up. Please check your number and try again.'=>'Vaši registraci se nepodařilo uložit. Zkontrolujte prosím své číslo a zkuste to znovu.','my account endpoint slugmessages'=>'Zprávy','Messages'=>'Zprávy','Text me updates about my orders'=>'Zasílejte mi aktualizace o mých objednávkách přes SMS','Text me offers and news from this store'=>'Zasílejte mi nabídky a novinky z tohoto obchodu prostřednictvím SMS','Send me offers and news from this store on WhatsApp'=>'Zasílejte mi nabídky a novinky z tohoto obchodu na WhatsApp','Order received'=>'Objednávka přijata','Payment received'=>'Platba byla přijata','Order on hold'=>'Objednávka pozastavena','Order shipped'=>'Objednávka odeslána','Order completed'=>'Objednávka dokončena','Ready for pickup'=>'Připraveno k vyzvednutí','Payment failed'=>'Platba se nezdařila','Order cancelled'=>'Objednávka byla zrušena','Order refunded'=>'Objednávka vrácena','Order update'=>'Aktualizace objednávky','Your message settings cover the mobile number on your orders with this store. Use the number from one of your orders.'=>'Vaše nastavení zpráv se vztahuje na mobilní číslo uvedené v objednávkách v tomto obchodě. Použijte číslo z jedné ze svých objednávek.','Your message settings are saved.'=>'Vaše nastavení zpráv bylo uloženo.','Done. This store will not send you any more messages.'=>'Hotovo. Tento obchod vám již nebude posílat žádné zprávy.','Please enter a mobile number with its country code, for example +44 7700 900123.'=>'Zadejte prosím mobilní číslo včetně předvolby země, například +44 7700 900123.','We could not save your settings just now. Please try again in a minute.'=>'Vaše nastavení se právě teď nepodařilo uložit. Zkuste to prosím znovu za minutu.','Your message settings cannot be shown just now. Please try again in a minute.'=>'Nastavení vašich zpráv nelze právě teď zobrazit. Zkuste to prosím znovu za minutu.','Messages from this store'=>'Zprávy z tohoto obchodu','Save'=>'Uložit','Stop all messages'=>'Zastavit všechny zprávy','Recent messages'=>'Nedávné zprávy','This store has not sent you any messages yet.'=>'Tento obchod vám zatím neposlal žádné zprávy.','%1$s, order %2$s, %3$s'=>'%1$s, objednávka %2$s, %3$s','Sign in to manage the messages this store sends you.'=>'Přihlaste se pro správu zpráv, které vám tento obchod posílá.','Zinn® message settings'=>'Nastavení zpráv Zinn®','Lets a signed-in shopper change the text messages your store sends them, stop them all, and see the last 20.'=>'Umožňuje přihlášenému zákazníkovi upravit textové zprávy, které mu váš obchod odesílá, zcela je zastavit a zobrazit posledních 20.','%s — guides and services'=>'%s – návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku k %s','Hide this'=>'Skrýt toto','Zinn® Pro Membership: every Pro plugin, one licence'=>'Členství v Zinn® Pro: každý plugin Pro, jedna licence','The Pro versions of Page Builder Sandwich, Tranzly, Zinn® SEO, Zinn® Cache and Zinn® Backups, and every Pro plugin we release next, from %s a year. A second membership adds Zinn® Chat Pro.'=>'Pro verze doplňků Page Builder Sandwich, Tranzly, Zinn® SEO, Zinn® Cache a Zinn® Backups a každý další Pro plugin, který vydáme, od %s ročně. Druhé členství přidává Zinn® Chat Pro.','Zinn® hosting for WordPress'=>'Zinn® hosting pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro ty, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zavedené weby, domény a umístění odkazů s tím, že peníze jsou bezpečně uschovány, dokud nebudou obě strany spokojeny.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tím živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globální tržiště na volné noze: prohlédněte si více než 10 000 hotových služeb od autorů, designérů, vývojářů a SEO specialistů, nebo zadejte projekt a nechte je podat nabídku.','See the Zinn Digital® release notes.'=>'Zobrazit poznámky k vydání Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Aktualizační služba Zinn® nevydala odkaz ke stažení této aktualizace. Zkontrolujte, zda se tato stránka může připojit k platformě Zinn®, a zkuste to znovu.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Aktualizaci se nepodařilo stáhnout ze služby aktualizací Zinn® (%s). Zkuste to prosím znovu za několik minut.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.','Order updates'=>'Aktualizace objednávky','Opted in (yes or no)'=>'Přihlášeno (ano nebo ne)','Channel (SMS or WhatsApp)'=>'Kanál (SMS nebo WhatsApp)','WhatsApp link'=>'Odkaz na WhatsApp','Message us on WhatsApp'=>'Napište nám na WhatsApp','Zinn® WhatsApp button'=>'Tlačítko WhatsApp od Zinn®','A button that opens a WhatsApp chat with your store. It shows only once your WhatsApp number is connected in Zinn® Campaigns.'=>'Tlačítko, které otevře konverzaci v aplikaci WhatsApp s vaším obchodem. Zobrazí se až po propojení vašeho čísla WhatsApp v Zinn® Campaigns.','Button settings'=>'Nastavení tlačítka','Button text'=>'Text tlačítka','Show to'=>'Zobrazit pro','Everyone'=>'Všichni','Shoppers not yet getting order updates'=>'Nakupující zatím nedostávají aktualizace objednávek','Connect your WhatsApp number in Zinn® Campaigns to show this button. Until then it shows nothing on your site.'=>'Pro zobrazení tohoto tlačítka připojte své číslo WhatsApp v Zinn® Campaigns. Do té doby se na vašem webu nic nezobrazí.']];